// Promo policy: max 3 promos per customer per local day (midnight to midnight
// in the customer's zone), at least 2 hours between two promos.
// Security alerts are transactional: never held, never counted.
// State is in memory (single process).
const DAILY_CAP = 3;
const MIN_GAP_MS = 2 * 60 * 60 * 1000;

export function createGate() {
  const sends = new Map(); // id -> { userId, category, ts }
  const promosByUser = new Map(); // userId -> Set of ids
  let seq = 0;

  function refuse(rule) {
    return { allowed: false, rule, id: null };
  }

  function request({ userId, timeZone, category, now }) {
    const ts = now instanceof Date ? now.getTime() : NaN;
    if (!Number.isFinite(ts)) return refuse("invalid-time");

    if (category === "security") {
      const id = `s${++seq}`;
      sends.set(id, { userId, category, ts });
      return { allowed: true, rule: "", id };
    }
    if (category !== "promo") return refuse("unknown-category");
    if (typeof timeZone !== "string" || !gkZoneOk(timeZone)) return refuse("invalid-time-zone");

    const ids = promosByUser.get(userId);
    const today = gkDayKey(ts, timeZone);
    let countToday = 0;
    if (ids) {
      for (const pid of ids) {
        const p = sends.get(pid);
        if (Math.abs(ts - p.ts) < MIN_GAP_MS) return refuse("promo-min-gap");
        if (gkDayKey(p.ts, timeZone) === today) countToday++;
      }
    }
    if (countToday >= DAILY_CAP) return refuse("daily-cap");

    const id = `p${++seq}`;
    sends.set(id, { userId, category, ts });
    if (!ids) promosByUser.set(userId, new Set([id]));
    else ids.add(id);
    return { allowed: true, rule: "", id };
  }

  function cancel(id) {
    const rec = sends.get(id);
    if (!rec) return;
    sends.delete(id);
    promosByUser.get(rec.userId)?.delete(id);
  }

  return { request, cancel };
}
EOF
